            raise
        # Ignore expected parsing errors
        if "cannot use --safe" in error_str or "INTERNAL ERROR" in error_str:
            pass


def main():
    """Main fuzzing entry point"""
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()


if __name__ == "__main__":
    main()

