                        obj = {"key": obj, "data": fdp.ConsumeUnicodeNoSurrogates(100)}
                    elif choice_type == 1:
                        obj = [obj, fdp.ConsumeInt(8), fdp.ConsumeFloat()]
                    elif choice_type == 2:
                        obj = fdp.ConsumeFloat()
